import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

/** Both actual Item definitions, including the older identical-text printing. */
public final class GeneratedRuleBatch66Test {
    static final UUID A=TurnDamageReductionTest.A,B=TurnDamageReductionTest.B;
    static final List<String> PRINTS=List.of("me5_en_110","me1_en_118");
    static void check(boolean b,String s){TurnDamageReductionTest.check(b,s);}
    static TurnDamageReductionTest.Config config(String id){var c=new TurnDamageReductionTest.Config();c.id=id;c.trainer=GeneratedRuleBatch8Test.trainer(id);c.definition=BundledRules.loadCardDefinitions().find(id).orElseThrow();return c;}
    public static void main(String[] args){printed();actual();firstTurnAndAuthority();copy();System.out.println("GeneratedRuleBatch66Test passed: both actual Iron Defender Items, complete printed programs, no-current-Metal use and later entrants, stacked reductions/live evolution, after-WR/Bench and bypass, first-turn Item use, unchanged Supporter quota, authority/stale/replay and actual copied attack");}
    static void printed(){for(String id:PRINTS){var c=config(id);check(c.definition.effectSupport()==EffectSupport.SUPPORTED&&c.definition.category()==CardCategory.TRAINER&&c.definition.trainerCategory()==TrainerCategory.ITEM&&c.definition.copyLimit()==4&&c.definition.regulationMark().equals("I"),"Actual Item metadata "+id);check(!c.trainer.endsTurn()&&c.trainer.category()==TrainerCategory.ITEM,"Iron Defender mistaken for Supporter/end-turn");var e=c.trainer.effectProgram().triggers().getFirst().effects().getFirst();var p=dev.hua.ptcglive.engine.effect.TurnDamageReduction.from(e);check(p.amount()==30&&p.recipients().types().equals(Set.of(EnergyType.METAL)),"Actual type/amount incorrect");}}
    static void actual(){for(String id:PRINTS)for(String mode:List.of("ONE","TWO","NO_METAL","LATER_METAL","EVOLVE_AWAY","NEW_BENCH","WEAK","RESIST","BYPASS","BENCH")){
        var c=config(id);if(Set.of("NO_METAL","LATER_METAL").contains(mode))c.types=Set.of(EnergyType.FIRE);if(mode.equals("EVOLVE_AWAY"))c.evolvedTypes=Set.of(EnergyType.FIRE);
        c.hit=TurnDamageReductionTest.hit(100,mode.equals("WEAK")?EnergyType.GRASS:mode.equals("RESIST")?EnergyType.FIGHTING:EnergyType.COLORLESS,mode.equals("BYPASS")?",\"ignoresActiveDefenderDamageEffects\":true":mode.equals("BENCH")?",\"damageTarget\":\"ALL_OPPONENT_POKEMON\"":"");
        var m=TurnDamageReductionTest.game(c);int turn=m.turnNumber(),rng=m.randomTranscript().size();var before=m.privateView(A);var card=TurnDamageReductionTest.play(m,A,id);check(m.currentPlayer().equals(A)&&m.turnNumber()==turn&&m.mayPlaySupporter(A)&&m.privateView(A).discard().contains(card)&&m.privateView(A).deck().equals(before.deck())&&m.randomTranscript().size()==rng,"Actual Item wrong play consequence");
        if(mode.equals("TWO"))TurnDamageReductionTest.play(m,A,id);if(Set.of("LATER_METAL","EVOLVE_AWAY").contains(mode))TurnDamageReductionTest.evolve(m,A);
        if(mode.equals("NEW_BENCH")){var added=TurnDamageReductionTest.hand(m,A,"own");m.playBasicPokemonToBench(A,added.instanceId());m.switchActiveByEffect(A,A,PokemonIdentityTestSupport.logical(m,A,added.instanceId()));}
        m.endTurn(A);m.attack(B,"hit");int expected=switch(mode){case "TWO","RESIST"->40;case "WEAK"->170;case "NO_METAL","EVOLVE_AWAY","BYPASS"->100;default->70;};check(m.activePokemonView(A).damage()==expected,"Actual defense "+id+" "+mode);if(mode.equals("BENCH"))check(m.benchPokemonView(A).getFirst().damage()==70,"Actual Bench unprotected");
    }}
    static void firstTurnAndAuthority(){for(String id:PRINTS){var c=config(id);c.later=false;var m=TurnDamageReductionTest.game(c);var card=TurnDamageReductionTest.hand(m,A,id);check(m.canPlayTrainer(A,card.instanceId(),null),"Item denied on first player's first turn");TurnDamageReductionTest.atomic(m,()->m.playTrainer(A,card.instanceId(),TurnDamageReductionTest.active(m,A)));TurnDamageReductionTest.atomic(m,()->m.playTrainer(B,TurnDamageReductionTest.hand(m,B,id).instanceId(),null));var s=MatchSession.multiplayer(m,A,B);var v=s.view(A,A);var option=v.options().stream().filter(o->o.cardKeys().contains("hand:"+card.instanceId())).findFirst().orElseThrow();s.submit(A,A,v.revision(),option.index());TurnDamageReductionTest.atomic(m,()->s.submit(A,A,v.revision(),option.index()));TurnDamageReductionTest.atomic(m,()->m.playTrainer(A,card.instanceId(),null));}}
    static void copy(){for(String id:PRINTS){var m=TurnDamageReductionTest.game(config(id));TurnDamageReductionTest.play(m,A,id);m.endTurn(A);var copy=CopyAttackTest.copier();for(int n=0;n<copy.energyCost().values().stream().mapToInt(Integer::intValue).sum();n++){var energy=TurnDamageReductionTest.hand(m,B,"energy");m.attachEnergyByEffect(B,B,EffectSourceZone.HAND,energy.instanceId(),B,TurnDamageReductionTest.active(m,B));}TemporaryReceivedDamageTest.copy(m,B,"hit");check(m.activePokemonView(A).damage()==70,"Copied actual source bypassed Iron Defender");}}
}
